"""Shared Contact Us layout; native Shopify form and honest local preview."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];T=R/'theme'
D=json.loads((R/'preview/reference-data.json').read_text(encoding='utf-8'))
def icon(paths):return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths+'</svg>'
phone=icon('<path d="M5 3H9L11 8L8 10Q10 15 15 17L17 14L22 16V20Q22 23 18 22Q4 19 2 7Q1 3 5 3Z"/>')
mail=icon('<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 6L12 13L21 6"/>')
pin=icon('<path d="M19 10C19 16 12 22 12 22S5 16 5 10A7 7 0 1 1 19 10Z"/><circle cx="12" cy="10" r="2"/>')
clock=icon('<circle cx="12" cy="12" r="9"/><path d="M12 6V12L16 15"/>')
hero='''<section class="container contact-hero"><div><span class="eyebrow">There is always room for a conversation</span><h1>Come, tell us<br><em>what’s cooking.</em></h1><p>A question about your order, a recipe to share, or just a hello. We would love to hear from you.</p><span class="contact-granny-line">“First, sit down. Then tell me everything.”</span></div><span class="art-wash contact-hero-art" aria-hidden="true"><img src="/assets/contact-kitchen.svg" alt="" width="600" height="330"></span></section>'''
details='<aside class="contact-details"><span class="eyebrow">Get in touch</span><h2>A little hello<br>goes a long way.</h2><p class="contact-response">We typically respond within 24 hours on business days.</p><dl class="contact-addresses"><div><dt>'+phone+'<span>Give us a call</span></dt><dd><a href="tel:+919347815723">+91 93478 15723</a></dd></div><div><dt>'+mail+'<span>Write to us</span></dt><dd><a href="mailto:contact@ammammas.in">contact@ammammas.in</a></dd></div><div><dt>'+pin+'<span>Our home</span></dt><dd>Hyderabad, Telangana, India</dd></div><div><dt>'+clock+'<span>Kitchen hours</span></dt><dd>Monday–Saturday<br>9 AM–6 PM IST</dd></div></dl><div class="contact-small-art art-wash" aria-hidden="true"><img src="/assets/tiffin.svg" alt=""></div></aside>'
form='''<section class="contact-form-card" aria-labelledby="ContactFormHeading"><span class="eyebrow">Leave us a note</span><h2 id="ContactFormHeading">What’s on your mind?</h2><p>Tell us a little about how we can help.</p><form class="contact-note-form"><div class="contact-field-row"><div class="contact-field"><label for="ContactName">Your name <span aria-hidden="true">*</span></label><input id="ContactName" name="contact[name]" autocomplete="name" placeholder="Your full name" required></div><div class="contact-field"><label for="ContactEmail">Email address <span aria-hidden="true">*</span></label><input id="ContactEmail" name="contact[email]" type="email" autocomplete="email" placeholder="you@example.com" required></div></div><div class="contact-field"><label for="ContactSubject">Subject <span aria-hidden="true">*</span></label><input id="ContactSubject" name="contact[subject]" placeholder="How can we help?" required></div><div class="contact-field"><label for="ContactBody">Your message <span aria-hidden="true">*</span></label><textarea id="ContactBody" name="contact[body]" rows="6" placeholder="Tell us more. If it is about an order, please include your order number." required></textarea></div><div class="contact-send-row"><button class="button" type="submit">Send your note <span aria-hidden="true">↗</span></button><small>* Required fields</small></div><p class="contact-preview-feedback" role="status" aria-live="polite"></p></form></section>'''
html='<div class="contact-page">'+hero+'<section class="container contact-layout">'+details+form+'</section><div class="container contact-ending"><span></span><p>A familiar voice. A little help. A whole lot of care.</p><span></span></div></div>'
D['contactPage']=html
(R/'preview/reference-data.json').write_text(json.dumps(D,ensure_ascii=False),encoding='utf-8')
(R/'preview/contact.html').write_text(html,encoding='utf-8')
native=html.replace('/assets/contact-kitchen.svg',"{{ 'contact-kitchen.svg' | asset_url }}").replace('/assets/tiffin.svg',"{{ 'tiffin.svg' | asset_url }}")
native=native.replace('<form class="contact-note-form">',"{% form 'contact', class: 'contact-note-form' %}{{ form.errors | default_errors }}{% if form.posted_successfully? %}<p class=\"contact-success\" role=\"status\">Thank you for your note. We will be in touch.</p>{% endif %}")
native=native.replace('<p class="contact-preview-feedback" role="status" aria-live="polite"></p></form>','{% endform %}')
(T/'sections/main-contact.liquid').write_text(native+'\n{% schema %}\n'+json.dumps({'name':'Contact us','settings':[]})+'\n{% endschema %}',encoding='utf-8')
# Keep both generated page templates pointing to the native form section.
(T/'templates/page.contact.json').write_text(json.dumps({'sections':{'main':{'type':'main-contact'}},'order':['main']},indent=2),encoding='utf-8')
print('Contact Us updated with shared artwork, captured contact details and a native Shopify form.')
